-- Aura Games transaction seed data
-- 3000 orders / order_items / payments, spanning 2019-2026
-- order_id, order_item.order_id, and payment.order_id are aligned
-- 1:1:1 (order N has exactly one order_item and one payment row)
-- ============================================================

-- ============ ORDERS ============






-- ============ ORDER ITEMS ============






-- ============ PAYMENTS ============






-- 1. For orders with a linked user, copy the user's email
UPDATE orders o
JOIN users u ON o.user_id = u.id
SET o.email = u.email
WHERE o.user_id IS NOT NULL;

-- 2. For guest orders (no user_id), generate a random email
UPDATE orders
SET email = CONCAT('guest_', SUBSTRING(MD5(RAND()), 1, 8), '@google.com')
WHERE user_id IS NULL;